/* PortfolioIQ MVP — dependency-free client. All financial data comes from the local FastAPI backend. */
'use strict';
const $ = (q,root=document)=>root.querySelector(q);
const $$ = (q,root=document)=>Array.from(root.querySelectorAll(q));
const fmt = (n,d=0)=>n == null ? '—' : new Intl.NumberFormat('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);
const usd = (n,d=2)=>n == null ? '—' : '$'+fmt(n,d);
const signedUSD = (n)=>n == null ? '—' : (n>=0?'+':'−')+'$'+fmt(Math.abs(n),2);
const pct = (n,d=2)=>n == null ? '—' : (n>=0?'+':'')+fmt(n,d)+'%';
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colorClass=n=>n==null?'muted':n>=0?'positive':'negative';
const COLORS=['#bcf3ab','#75d4b9','#74a2ac','#d6be84','#8d8bd3','#dd987f','#8eb878','#b2aebd','#719d87','#637d9a','#b4a48b'];
const iconPaths={
  layout:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',
  activity:'<path d="M22 12h-4l-3 9L9 3l-3 9H2"/>',
  sliders:'<path d="M4 7h9m5 0h2M4 17h2m5 0h9"/><circle cx="16" cy="7" r="3"/><circle cx="8" cy="17" r="3"/>',
  sparkles:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3ZM19 16l.8 2.2L22 19l-2.2.8L19 22l-.8-2.2L16 19l2.2-.8L19 16ZM5 3l.5 1.5L7 5l-1.5.5L5 7l-.5-1.5L3 5l1.5-.5L5 3Z"/>',
  book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',
  info:'<circle cx="12" cy="12" r="10"/><path d="M12 16v-4m0-4h.01"/>',
  upload:'<path d="M12 16V3m0 0L7 8m5-5 5 5M5 17v4h14v-4"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  'arrow-up':'<path d="m7 14 5-5 5 5"/>',
  'arrow-down':'<path d="m7 10 5 5 5-5"/>',
  'chart':'<path d="M3 3v18h18M7 14l4-4 4 3 5-7"/>',
  pie:'<path d="M21.21 15.89A10 10 0 1 1 8.11 2.79"/><path d="M22 12A10 10 0 0 0 12 2v10Z"/>',
  coins:'<path d="M12 2v20M17 5c-2-2-8-2-9 1-2 5 10 3 10 9-1 4-8 5-12 1"/>',
  shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/>',
  search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
  cross:'<path d="M18 6 6 18M6 6l12 12"/>',
  help:'<circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3h.01"/>',
  clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  check:'<path d="M20 6 9 17l-5-5"/>',
  alert:'<path d="m10.3 3.7-8.2 14a2 2 0 0 0 1.7 3h16.4a2 2 0 0 0 1.7-3l-8.2-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',
  send:'<path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/>',
  file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8ZM14 2v6h6M8 13h8m-8 4h8"/>',
  layers:'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 10 9 5 9-5m-18 5 9 5 9-5"/>',
  lock:'<rect x="4" y="11" width="16" height="11" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>',
  refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 9a8 8 0 0 1 14-2l1 5M4 12l1 5a8 8 0 0 0 14-2"/>'
};
const svg=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.info}</svg>`;
const state={transactions:[],xray:null,stressCompare:null,stressDetail:null,aiAvailable:false,useAI:false,view:'overview',portfolio:'growth',portfolios:[],data:null,period:'6M',scenarioPreset:'market',shocks:{equity:-20,fixed_income:-5,commodity:3,cash:0},scenarioResult:null,chat:[],search:'',sort:'value',loading:false};
const PRESETS={market:{name:'Market sell-off',detail:'Broad equity decline with modest fixed-income weakness',icon:'activity',shocks:{equity:-20,fixed_income:-5,commodity:3,cash:0}},tech:{name:'Technology correction',detail:'Larger shocks to direct technology and growth exposure',icon:'chart',shocks:{equity:-8,fixed_income:1,commodity:0,cash:0}},rates:{name:'Rates rise',detail:'Equities and fixed income reprice under a rate shock',icon:'sliders',shocks:{equity:-7,fixed_income:-9,commodity:2,cash:0}},recovery:{name:'Risk-on recovery',detail:'Hypothetical market recovery across asset classes',icon:'arrow-up',shocks:{equity:14,fixed_income:2,commodity:4,cash:0}},custom:{name:'Custom scenario',detail:'Choose percentage shocks for major asset classes',icon:'target',shocks:{equity:-15,fixed_income:-4,commodity:0,cash:0}}};
const pageNames={overview:'Overview',holdings:'Holdings',xray:'Portfolio X-Ray',risk:'Risk intelligence',scenarios:'Scenario studio',analyst:'IQ analyst',ledger:'Transactions & prices',methodology:'Methodology'};

async function api(url,options={}){
  const response=await fetch(url,options);
  const body=await response.json().catch(()=>({detail:'Unexpected response'}));
  if(!response.ok)throw new Error(typeof body.detail==='string'?body.detail:JSON.stringify(body.detail||'Request failed'));
  return body;
}
function toast(message,warning=false){const el=$('#toast');el.textContent=message;el.style.borderColor=warning?'#a46a56':'#4e7563';el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4400)}
function fillStaticIcons(){$$('[data-icon]').forEach(el=>{el.innerHTML=svg(el.dataset.icon)});}
function pageHeader(eyebrow,title,sub,actions=true){
  return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${actions?`<div class="head-actions"><div class="select-wrap"><select id="portfolioSelect" class="portfolio-select" aria-label="Choose portfolio">${state.portfolios.map(p=>`<option value="${esc(p.id)}" ${p.id===state.portfolio?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><button class="btn btn-primary" data-action="import">${svg('upload',15)} Import holdings</button></div>`:''}</div>`;
}
function banner(){const d=state.data;const led=d.portfolio.ledger_enabled;return `<div class="data-banner">${svg('info')}<span><b>${led?(d.portfolio.is_demo?'Fictional ledger laboratory':'Transaction accounting'):d.portfolio.is_demo?'Synthetic demonstration':'Current holdings import'}.</b> ${esc(d.data_notice)} ${!led&&d.portfolio.is_demo?'Performance is a simulated fixed-holdings path, not audited account returns.':''}</span></div>`}
function statCard(label,value,footer,icon,extra=''){return `<article class="card stat-card ${extra}"><div class="stat-label">${svg(icon,15)} ${esc(label)}</div><div class="stat-number ${extra==='hero'?'lg':''}">${value}</div><div class="stat-foot">${footer}</div></article>`}
function lineChart(data,options={}){
  if(!data||data.length<2)return `<div class="empty-state">${svg('chart',30)}<h3>Historical series unavailable</h3><p>Import dated closing prices via Transactions & prices.</p></div>`;
  const field=options.field||'value',compare=options.compare&&data.every(r=>Number.isFinite(r[options.compare]))?options.compare:null;
  const W=760,H=285,L=47,R=12,T=16,B=33,PLOTW=W-L-R,PLOTH=H-T-B;
  let values=data.map(r=>r[field]);if(compare)values=values.concat(data.map(r=>r[compare]));
  let mn=Math.min(...values),mx=Math.max(...values);let pad=Math.max((mx-mn)*.12,Math.max(Math.abs(mx),1)*.018);
  mn-=pad;mx+=pad;if(options.zeroTop)mx=Math.max(0,mx);
  const xp=i=>L+i/(data.length-1)*PLOTW;
  const yp=v=>T+(mx-v)/(mx-mn)*PLOTH;
  const coords=key=>data.map((d,i)=>`${i?'L':'M'}${xp(i).toFixed(2)},${yp(d[key]).toFixed(2)}`).join(' ');
  const points=data.map((d,i)=>`${xp(i).toFixed(2)},${yp(d[field]).toFixed(2)}`).join(' ');
  const area=`M${xp(0).toFixed(2)},${(H-B).toFixed(2)} ${coords(field)} L${xp(data.length-1).toFixed(2)},${(H-B).toFixed(2)} Z`;
  const ticks=[0,.25,.5,.75,1].map(t=>{const val=mn+(mx-mn)*t,y=yp(val);const label=options.format==='pct'?`${val.toFixed(1)}%`:options.format==='index'?val.toFixed(1):'$'+(val/1000).toFixed(0)+'k';return `<line class="gridline" x1="${L}" x2="${W-R}" y1="${y}" y2="${y}"/><text class="axis" x="${L-9}" y="${y+4}" text-anchor="end">${label}</text>`}).join('');
  const dates=[0,.25,.5,.75,1].map(t=>{const i=Math.min(data.length-1,Math.round((data.length-1)*t));const d=new Date(`${data[i].date}T00:00:00`);const label=d.toLocaleDateString('en-US',{month:'short',day:data.length<50?'numeric':undefined});return `<text class="axis" x="${xp(i)}" y="${H-8}" text-anchor="middle">${label}</text>`}).join('');
  const uid=options.field==='drawdown'?'ddgrad':'eqgrad';
  return `<svg class="line-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(options.label||'Portfolio value chart')}"><defs><linearGradient id="${uid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${options.field==='drawdown'?'#e8a89a':'#baf2ad'}" stop-opacity=".23"/><stop offset="1" stop-color="#baf2ad" stop-opacity="0"/></linearGradient></defs>${ticks}${dates}<path d="${area}" fill="url(#${uid})"/>${compare?`<path d="${coords(compare)}" fill="none" stroke="#7d98a3" stroke-width="2" stroke-dasharray="5 6" stroke-linejoin="round"/>`:''}<path d="${coords(field)}" fill="none" stroke="${options.field==='drawdown'?'#e7aa9b':'#baf2ad'}" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${xp(data.length-1)}" cy="${yp(data[data.length-1][field])}" r="4.2" fill="#c6f5b6" stroke="#122017" stroke-width="2"/></svg>`;
}
function donut(allocation){if(!allocation.length)return '<div class="empty-state">No priced positions yet. Add transactions and historical prices.</div>';const items=allocation.slice(0,7),rest=allocation.slice(7).reduce((s,v)=>s+v.weight,0);if(rest>0)items.push({name:'Other',weight:rest});let cursor=0;const stops=items.map((v,i)=>{const start=cursor;cursor+=v.weight;return `${COLORS[i%COLORS.length]} ${start}% ${cursor}%`});const top=items[0];return `<div class="donut-layout"><div class="donut" style="background:conic-gradient(${stops.join(',')})"><div class="donut-center"><strong>${top?fmt(top.weight,1):0}%</strong><small>Largest category</small></div></div></div><div class="allocation-list">${items.map((v,i)=>`<div class="allocation-row"><span class="swatch" style="background:${COLORS[i%COLORS.length]}"></span><span>${esc(v.name)}</span><strong>${fmt(v.weight,1)}%</strong></div>`).join('')}</div>`}
function holdingsTable(rows,{max=0,large=false}={}){const visible=max?rows.slice(0,max):rows;return `<div class="table-scroll"><table class="holdings-table ${large?'table-large':''}"><thead><tr><th>ASSET</th><th>TYPE</th><th class="right">VALUE</th><th class="right">WEIGHT</th><th class="right">UNREALIZED P/L</th></tr></thead><tbody>${visible.map(h=>`<tr><td><div class="ticker-cell"><span class="ticker-symbol">${esc(h.symbol.slice(0,3))}</span><span><b>${esc(h.symbol)}</b><small title="${esc(h.name)}">${esc(h.name)}</small></span></div></td><td><span class="ticker-swatch">${esc(h.asset_class)}</span></td><td class="right">${usd(h.value)}</td><td class="right">${h.weight==null?'—':fmt(h.weight,1)+'%'}</td><td class="right ${colorClass(h.unrealized_pl)}">${signedUSD(h.unrealized_pl)}</td></tr>`).join('')}</tbody></table></div>`}
function insightsCard(){const items=state.data.insights;return `<div class="card insights-card"><div class="card-title-row"><div><div class="card-title">Intelligence feed</div><div class="card-subtitle">Calculated signals from your portfolio</div></div><span class="tiny-label">${items.length} INSIGHTS</span></div>${items.map(it=>`<div class="insight"><div class="insight-icon ${esc(it.severity)}">${svg(it.severity==='warning'?'alert':it.severity==='positive'?'check':'info',17)}</div><div><div class="insight-title">${esc(it.title)}</div><div class="insight-copy">${esc(it.description)}</div></div></div>`).join('')}</div>`}
function renderOverview(){if(state.data.portfolio.ledger_enabled)return renderLedgerOverview();const d=state.data,s=d.summary;const time=s.period_return!=null;const data=periodData();return `${pageHeader('PORTFOLIO OVERVIEW','Your investment command center','A clearer view of your money, risk, and what drives performance.')}${banner()}
<div class="grid stats-grid">
  ${statCard('Total portfolio value',usd(s.total_value),`${svg('briefcase',13)} ${s.position_count} positions · ${usd(d.portfolio.cash,0)} cash`,'coins','hero')}
  ${statCard('6-month demo return',time?pct(s.period_return):'Not available',time?`<span class="${colorClass(s.period_return)}">${svg(s.period_return>=0?'arrow-up':'arrow-down',14)} </span>Fixed-holdings simulation`:'No historical prices','chart')}
  ${statCard('6-month benchmark',time?pct(s.benchmark_return):'Not available',time?'Synthetic reference series':'No benchmark history','activity')}
  ${statCard('Unrealized P/L',signedUSD(s.unrealized_pl),`<span class="${colorClass(s.unrealized_pl)}">${s.cost_basis?fmt(s.unrealized_pl/s.cost_basis*100,2):'—'}% of cost basis</span>`,'target')}
</div>
<div class="primary-grid">
 <section class="card chart-card"><div class="card-title-row"><div><div class="card-title">Portfolio performance</div><div class="card-subtitle">Synthetic buy-and-hold value vs. simulated benchmark · USD</div></div><div class="segmented" role="group" aria-label="Chart period">${['1M','3M','6M'].map(p=>`<button class="${state.period===p?'active':''}" data-period="${p}">${p}</button>`).join('')}</div></div><div class="chart-container">${lineChart(data,{compare:'benchmark'})}</div><div class="line-legend"><span class="legend-item"><span class="legend-line"></span>Portfolio value</span><span class="legend-item"><span class="legend-line benchmark"></span>Simulated reference</span></div></section>
 <section class="card allocation-card"><div class="card-title-row"><div><div class="card-title">Portfolio allocation</div><div class="card-subtitle">Reported sector or fund category</div></div>${svg('pie',18)}</div>${donut(d.allocation)}</section>
</div>
<div class="bottom-grid">
 <section class="card holdings-card"><div class="card-title-row"><div><div class="card-title">Your top holdings</div><div class="card-subtitle">Largest positions by current market value</div></div><button class="view-link" data-view="holdings">View all ${svg('arrow',13)}</button></div>${holdingsTable(d.holdings,{max:5})}</section>
 ${insightsCard()}
</div>`}
function periodData(){const a=state.data.history;if(!a.length)return [];return a.slice(-({"1M":22,"3M":66,"6M":130}[state.period]||182));}
function renderHoldings(){const d=state.data,s=d.summary;let rows=[...d.holdings];if(state.sort==='pl')rows.sort((a,b)=>b.unrealized_pl-a.unrealized_pl);if(state.sort==='weight')rows.sort((a,b)=>b.weight-a.weight);rows=rows.filter(h=>(h.symbol+' '+h.name+' '+h.sector).toLowerCase().includes(state.search.toLowerCase()));return `${pageHeader('YOUR ASSETS','Portfolio holdings','Every position, its current value, allocation weight, and unrealized gain or loss.')}${banner()}<div class="grid stats-grid">${statCard('Holdings value',usd(s.total_value==null?null:s.total_value-d.portfolio.cash),'Excludes cash','coins','hero')}${statCard('Total positions',fmt(s.position_count),'Unique security symbols','briefcase')}${statCard('Top-three weight',s.top_3_concentration==null?'—':fmt(s.top_3_concentration,1)+'%','Concentration across direct positions','pie')}${statCard('Unrealized P/L',signedUSD(s.unrealized_pl),'Versus imported or sample cost basis','chart')}</div><section class="card full-card"><div class="card-title-row"><div><div class="card-title">All positions</div><div class="card-subtitle">Prices reflect your imported CSV or simulated demonstration values</div></div><button class="export-btn" data-action="export">${svg('download',14)} Export current holdings</button></div><div class="table-toolbar" style="margin-top:20px"><div class="searchbox">${svg('search')}<input id="holdingsSearch" placeholder="Search ticker, company, sector..." value="${esc(state.search)}" aria-label="Search holdings"/></div><select class="portfolio-select" id="sortSelect" style="min-width:145px"><option value="value" ${state.sort==='value'?'selected':''}>Sort: Value</option><option value="weight" ${state.sort==='weight'?'selected':''}>Sort: Weight</option><option value="pl" ${state.sort==='pl'?'selected':''}>Sort: P/L</option></select></div><div id="holdingsResults">${holdingsTable(rows,{large:true})}</div><div class="notice">${d.portfolio.ledger_enabled?'Raw daily closes are user/imported or provider-sourced, with a 7-day stale-price cutoff. Trades, dividends, fees and splits are accounted for. No tax-lot accounting or live prices.':'Assets are not priced from live exchanges. Imported CSV values are treated as user-provided USD amounts; taxes, fees, dividend entitlements and currency conversion are not calculated.'}</div></section>`}
function holdingsSearchUpdate(){let rows=[...state.data.holdings];rows=rows.filter(h=>(h.symbol+' '+h.name+' '+h.sector).toLowerCase().includes(state.search.toLowerCase()));if(state.sort==='pl')rows.sort((a,b)=>b.unrealized_pl-a.unrealized_pl);if(state.sort==='weight')rows.sort((a,b)=>b.weight-a.weight);$('#holdingsResults').innerHTML=rows.length?holdingsTable(rows,{large:true}):'<div class="empty-state">No matching assets.</div>';}
function metricCard(title,val,detail){return `<article class="card metric-card"><div class="stat-label">${esc(title)} ${svg('info',13)}</div><div class="metric-value">${val}</div><div class="metric-detail">${esc(detail)}</div></article>`}
function heatmap(cor){if(!cor)return '<div class="empty-state">Historical pairwise correlations cannot be computed from current positions alone.</div>';const n=cor.symbols.length;return `<div class="heatmap" style="--n:${n}"><div class="heatmap-row"><span></span>${cor.symbols.map(s=>`<span class="heatmap-label">${esc(s)}</span>`).join('')}</div>${cor.matrix.map((row,i)=>`<div class="heatmap-row"><span class="heatmap-label">${esc(cor.symbols[i])}</span>${row.map(v=>{const opacity=Math.max(.12,Math.abs(v)*.7);const bg=v>=0?`rgba(118,204,166,${opacity})`:`rgba(208,128,132,${opacity})`;return `<span class="heatmap-cell" title="Correlation: ${v.toFixed(2)}" style="background:${bg}">${v.toFixed(2)}</span>`}).join('')}</div>`).join('')}</div>`}
function renderRisk(){const d=state.data,r=d.risk;return `${pageHeader('RISK INTELLIGENCE','Know your downside','Quantify concentration, historical-style risk, and the relationships between assets.')}${banner()}${r?`<div class="mini-grid">${metricCard('Annualized volatility',fmt(r.volatility,2)+'%',d.portfolio.ledger_enabled?'Daily TWR-derived return volatility × √252':'Standard deviation of daily simulated returns × √252')}${metricCard('Sharpe ratio',fmt(r.sharpe,2),'Illustrative excess return per unit of volatility')}${metricCard('Maximum drawdown',fmt(r.max_drawdown,2)+'%',d.portfolio.ledger_enabled?'Peak-to-trough unit-NAV decline':'Largest peak-to-trough decline in the simulated path')}${metricCard('Beta to benchmark',fmt(r.beta,2),d.portfolio.ledger_enabled?'Unavailable: no benchmark feed assigned':'Sensitivity to the synthetic equity reference')}${metricCard('Daily historical VaR (95%)',fmt(r.var_95_daily,2)+'%','5th-percentile historical daily TWR; not a worst-case loss')}${metricCard('Daily historical CVaR (95%)',fmt(r.cvar_95_daily,2)+'%','Mean of worst 5% of observed daily returns')}${metricCard('Sortino ratio',fmt(r.sortino,2),'Excess return relative to downside deviation')}${metricCard('Tracking error',fmt(r.tracking_error,2)+'%',d.portfolio.ledger_enabled?'Unavailable: no benchmark data':'Annualized deviation of active daily returns')}</div>`:`<div class="card full-card"><div class="empty-state">${svg('shield',32)}<h3>Risk metrics need historical prices</h3><p>We don't manufacture volatility, drawdowns or beta for imported holdings.</p></div></div>`}
<div class="risk-main-grid"><section class="card full-card"><div class="card-title-row"><div><div class="card-title">Drawdown analysis</div><div class="card-subtitle">Peak-to-trough change over the available simulated price path</div></div>${svg('activity',18)}</div>${r?`<div class="chart-container">${lineChart(d.drawdown_history,{field:'drawdown',format:'pct',zeroTop:true,label:d.portfolio.ledger_enabled?'Observed ledger portfolio drawdown':'Simulated portfolio drawdown'})}</div>`:'<div class="empty-state">Drawdown chart unavailable</div>'}</section><section class="card full-card"><div class="card-title-row"><div><div class="card-title">Asset correlation matrix</div><div class="card-subtitle">Synthetic daily price returns · values from −1 to +1</div></div>${svg('layers',18)}</div><div id="correlationContainer" class="empty-state">Loading matrix...</div></section></div>
<div class="explain-panel">${svg('shield')}<span><b>Understand these numbers:</b> ${d.portfolio.ledger_enabled?'Ledger risk values use supplied unadjusted closing prices and cash-flow-adjusted daily returns. No benchmark-derived beta or tracking error is inferred. Daily prices may be delayed or stale, and risk measures are not forecasts.':'Demo correlations, VaR and volatility use fictitious price paths and are not assessments of actual market risk.'}</span></div>`}
function renderScenarios(){const d=state.data;return `${pageHeader('SCENARIO ANALYSIS','Scenario studio','Stress-test the current holdings. Change assumptions, compare outcomes, and inspect the impact.')}${banner()}<div class="scenario-layout"><section class="card scenario-picker"><div class="card-title">Choose a market scenario</div><div class="card-subtitle">Illustrative, deterministic percentage shocks</div>${Object.entries(PRESETS).map(([key,v])=>`<button class="scenario-option ${state.scenarioPreset===key?'active':''}" data-preset="${key}"><span class="radio-dot"></span><span><b>${esc(v.name)}</b><small>${esc(v.detail)}</small></span></button>`).join('')}${state.scenarioPreset==='custom'?`<div class="slider-group"><div class="card-title">Adjust shock assumptions</div>${[['equity','Equities / equity ETFs'],['fixed_income','Fixed income'],['commodity','Commodity ETFs'],['cash','Cash']].map(([key,title])=>`<div class="slider-row"><div class="slider-head"><span>${title}</span><b id="sliderLabel_${key}">${pct(state.shocks[key],0)}</b></div><input type="range" data-shock="${key}" min="-75" max="75" step="1" value="${state.shocks[key]}" aria-label="${title} shock"/></div>`).join('')}<button class="btn btn-primary" style="width:100%;margin-top:17px" data-action="run-scenario">Run custom scenario ${svg('arrow',14)}</button></div>`:''}<p class="scenario-note">For the technology preset, direct technology holdings and growth ETFs receive additional shocks. All other categories use simplified model assumptions.</p></section><section class="card scenario-result"><div class="card-title-row"><div><div class="card-title">Scenario impact</div><div class="card-subtitle">Estimated portfolio value under selected input shocks</div></div><span class="plain-tag">WHAT-IF MODEL</span></div><div id="scenarioResults">${state.scenarioResult?scenarioResultHTML(state.scenarioResult):'<div class="initial-loading"><div class="loading-ring"></div>Calculating scenario...</div>'}</div></section></div><div class="explain-panel" style="margin-top:18px">${svg('info')}<span><b>Model limitations:</b> Scenario shocks are illustrative inputs, not statistically derived forecasts or investment recommendations. No portfolio rebalancing, tax impact, transaction cost, or path dependency is assumed. Presets are not forecasts of specific economic events.</span></div>`}
function scenarioResultHTML(s){const neg=s.change<0;const maxImpact=Math.max(...s.breakdown.map(x=>Math.abs(x.impact)),1);return `<div class="results-hero"><small>Estimated portfolio value</small><div class="results-number">${usd(s.after)}</div><div class="result-badges"><span class="${colorClass(s.change)}">${signedUSD(s.change)}</span><span class="${colorClass(s.change)}">${pct(s.change_pct)}</span><span class="pale">vs. ${usd(s.before)} base</span></div><div class="delta-bar"><div class="impact" style="width:${neg?Math.max(0,Math.min(100,-s.change_pct)):0}%"></div><div class="remaining" style="width:${neg?Math.max(0,Math.min(100,100+s.change_pct)):100}%"></div></div><div class="bar-labels"><span>Impact ${pct(s.change_pct)}</span><span>After ${usd(s.after)}</span></div></div><div class="card-title">Impact by position</div><div class="card-subtitle">Dollar contribution to the modeled change</div><div class="impact-list">${s.breakdown.slice().sort((a,b)=>Math.abs(b.impact)-Math.abs(a.impact)).map(h=>`<div class="impact-row"><b>${esc(h.symbol)}</b><div class="impact-track"><div class="impact-fill ${h.impact>=0?'up':''}" style="width:${Math.max(0,Math.abs(h.impact)/maxImpact*100).toFixed(1)}%"></div></div><span class="right ${colorClass(h.impact)}">${signedUSD(h.impact)}</span></div>`).join('')}</div><div class="notice">${esc(s.methodology)}</div>`}
function renderAnalyst(){return `${pageHeader('PORTFOLIO INTELLIGENCE','Ask better questions','Explore your numbers in plain English, with transparent calculations and sources.')}${banner()}<div class="analyst-layout"><section class="card chat-card"><div class="chat-head"><div class="analyst-avatar">${svg('sparkles',23)}</div><div><b>PortfolioIQ Analyst</b><small>Calculation-grounded explanations · ${esc(state.data.portfolio.name)}</small></div><span class="chat-status">GUIDED MODE</span></div><div class="chat-area" id="chatArea">${state.chat.length?state.chat.map(m=>chatHTML(m)).join(''):`<div class="chat-message"><div class="chat-role-avatar">IQ</div><div class="chat-bubble">Welcome to PortfolioIQ. I can help explain your portfolio's performance, concentration, risk metrics, and modeled scenarios. Every number comes from the portfolio calculation engine.<br><br>Try one of the suggested questions, or ask your own.</div></div>`}</div><div class="chat-bottom"><form id="chatForm" class="chat-compose"><input id="chatInput" type="text" placeholder="Ask about your portfolio..." maxlength="1200" autocomplete="off" aria-label="Message PortfolioIQ Analyst" required/><button class="chat-send" aria-label="Send message" type="submit">${svg('send',17)}</button></form><div class="chat-caption">Guided answers, not a large language model. Educational use only.</div></div></section><aside class="card suggestion-card"><div class="card-title">Suggested questions</div><div class="card-subtitle">Start with a deeper look at your portfolio</div><div class="prompt-list">${['What is my biggest portfolio risk?','Am I too concentrated in one sector?','How has my portfolio performed versus the benchmark?','What happens in a market crash?'].map(x=>`<button class="prompt-button" data-prompt="${esc(x)}">${esc(x)} ${svg('arrow',15)}</button>`).join('')}</div><div class="divider"></div><div class="card-title">About this analyst</div><p class="helper">This first release uses deterministic financial tools and guided answer templates. It does not make unverified LLM claims or execute investment trades.</p><div class="explain-panel" style="margin-top:15px">${svg('lock')}<span>Portfolio analysis runs inside the local app. No brokerage credentials or external AI service are needed.</span></div></aside></div>`}
function chatHTML(m){return `<div class="chat-message ${m.role==='user'?'user':''}"><div class="chat-role-avatar">${m.role==='user'?'YOU':'IQ'}</div><div class="chat-bubble">${esc(m.text)}${m.sources?.length?`<div class="sources">${svg('check',12)} ${m.sources.map(s=>esc(s.label)).join(' · ')}</div>`:''}</div></div>`}
function renderMethodology(){return `${pageHeader('TRANSPARENCY CENTER','Data & methodology','Know what the platform calculates, what it assumes, and what it cannot yet provide.',false)}<div class="data-banner">${svg('shield')}<span><b>Research and education only.</b> PortfolioIQ is not an investment adviser, brokerage, or a source of personalized recommendations. Sample assets and all demo prices are synthetic.</span></div><div class="method-cards"><section class="card method-card"><h3>What is real in this build?</h3><p>The financial calculations, CSV import validation, SQLite persistence, allocation grouping, scenario computations, analyst responses and statistical functions are implemented. The demo price histories are reproducibly generated.</p></section><section class="card method-card"><h3>What is simulated?</h3><p>All default portfolios, their transaction-free price histories, benchmark values, and scenario shocks. Real company tickers in the sample do not imply real or current quotes. Risk metrics calculated from synthetic paths are demonstrations, not assessments of market risk.</p></section><section class="card method-card"><h3>How performance is computed</h3><p>Ledger portfolios calculate daily time-weighted returns net of external flows using an end-of-day flow convention, and annualized XIRR from dated investor cash flows and terminal NAV. Prices are unadjusted closes and splits/dividends must be separately recorded.</p><p>Demo historical value is the value of fixed quantities of each security, plus constant cash, across 130 synthetic business dates. Period return is ending value divided by starting value minus one. It is a <b>simulated buy-and-hold return</b>, not a historical account-level TWR or XIRR.</p></section><section class="card method-card"><h3>Risk measurement</h3><p>Annualized volatility uses sample daily standard deviation × √252. The Sharpe calculation assumes an illustrative 3.5% annual risk-free rate. Beta is estimated from covariance relative to the simulated benchmark. Historical VaR is the 5th-percentile daily return; CVaR is the mean below that threshold.</p></section><section class="card method-card"><h3>Imported portfolio limitations</h3><p>Uploaded CSV rows contain symbol, security name, sector, asset class, quantity, average unit cost and current unit price. These values are treated as inputs, not live quotes. Historical returns, beta, VaR, correlations and drawdowns remain unavailable because time-series data was not supplied.</p></section><section class="card method-card"><h3>Privacy & security boundaries</h3><p>This is a local, single-user development application, not an internet-facing multi-tenant product. Imported data persists in local SQLite. No account connections, authentication, custody, order placement, user isolation, cloud encryption or automated data removal are implemented yet.</p></section><section class="card method-card"><h3>AI roadmap</h3><p>Guided mode explains deterministic portfolio calculations locally. An optional, explicitly consented LLM analyst can request allowlisted read-only financial tools when OPENAI_API_KEY is configured on the server. Real-provider validation, SEC source retrieval, independently scored numeric evaluation, and authenticated cloud deployment remain future work.</p></section><section class="card method-card"><h3>Path to production</h3><p>Connect licensed adjusted prices and security identifiers, implement cash flow accounting and corporate actions, reconcile brokerage imports, add authentication and authorization, validate risk models against independent references, review licensing/compliance and perform a third-party security audit.</p></section></div>`}

function renderLedgerOverview(){
 const d=state.data,s=d.summary;return `${pageHeader('TRANSACTION ACCOUNTING','Performance, without the guesswork','Track cash flows and measure how your invested capital actually performed.')}${banner()}
 <div class="grid stats-grid">
 ${statCard('Total portfolio value',usd(s.total_value),`${fmt(s.position_count)} positions · ${usd(d.portfolio.cash)} cash`, 'coins','hero')}
 ${statCard('Time-weighted return',pct(s.period_return), 'Daily chain-linked TWR · external flows excluded','chart')}
 ${statCard('Money-weighted XIRR',pct(s.xirr), 'Annualized; sensitive to investment timing','activity')}
 ${statCard('Net contributions',usd(s.net_contributions),'Deposits minus withdrawals','target')}
 </div>
 <div class="primary-grid"><section class="card chart-card"><div class="card-title-row"><div><div class="card-title">Flow-adjusted performance</div><div class="card-subtitle">Unit NAV indexed to 100 · no synthetic benchmark</div></div><div class="segmented">${['1M','3M','6M'].map(p=>`<button class="${state.period===p?'active':''}" data-period="${p}">${p}</button>`).join('')}</div></div>${lineChart(periodData(),{field:'unit_nav',format:'index',label:'Flow-adjusted portfolio return index'})}<div class="notice">Value histories based on cash flows and sourced raw daily closing prices. Deposits and withdrawals are excluded using an end-of-day convention.</div></section><section class="card allocation-card"><div class="card-title-row"><div><div class="card-title">Current exposure</div><div class="card-subtitle">Priced securities and cash</div></div>${svg('pie',17)}</div>${donut(d.allocation)}</section></div>
 <div class="bottom-grid"><section class="card full-card"><div class="card-title-row"><div><div class="card-title">Ledger accounting</div><div class="card-subtitle">Realized results and cash income</div></div><button class="view-link" data-view="ledger">Manage activity ${svg('arrow',13)}</button></div><div class="ledger-summary-line"><span>Realized gains/losses</span><b class="${colorClass(s.realized_pl)}">${signedUSD(s.realized_pl)}</b></div><div class="ledger-summary-line"><span>Unrealized gains/losses</span><b class="${colorClass(s.unrealized_pl)}">${signedUSD(s.unrealized_pl)}</b></div><div class="ledger-summary-line"><span>Received dividends</span><b>${usd(s.dividend_income)}</b></div><div class="ledger-summary-line"><span>Recorded fees</span><b>${usd(s.fees)}</b></div><div class="ledger-summary-line"><span>Price valuation date</span><b>${esc(s.valuation_date)}</b></div></section>${insightsCard()}</div>`;
}
function renderLedger(){
 const d=state.data;
 if(!d.portfolio.ledger_enabled)return `${pageHeader('TRANSACTION ACCOUNTING','Transactions & price history','Create a new transaction-based portfolio for accurate cash flows and return calculation.')}${banner()}<div class="card full-card"><h2 style="margin:0 0 9px">Create a ledger-based portfolio</h2><p class="helper">Existing holdings-only and classic synthetic demo portfolios are unchanged. Ledger portfolios start with zero cash; record a deposit, trades, and daily closing prices.</p><form id="ledgerCreateForm" class="ledger-create-form"><label>Portfolio name <input class="form-control" name="name" value="My Long-Term Portfolio" maxlength="75" required></label><button type="submit" class="btn btn-primary">${svg('coins',15)} Create portfolio</button></form><div class="notice">For a worked example, select <b>Ledger Lab</b> in the portfolio selector above.</div></div>`;
 const s=d.summary,readonly=d.portfolio.is_demo;
 const types=['DEPOSIT','WITHDRAWAL','BUY','SELL','DIVIDEND','FEE','SPLIT'];
 return `${pageHeader('TRANSACTION ACCOUNTING','Transactions & price history','Record real cash activity, shares, dividends, splits, and dated closing prices.')}${banner()}<div class="ledger-top-actions"><span>${readonly?'Explore the worked example, or start your own transaction ledger.':'Add cash activity first, then trades, and finally historical closing prices.'}</span><button class="btn btn-secondary" data-action="new-ledger">${svg('coins',14)} New ledger portfolio</button></div>
 <div class="grid stats-grid">${statCard('Cash balance',usd(d.portfolio.cash),'After all recorded transactions','coins')}${statCard('Net deposits',usd(s.net_contributions),'Deposits less withdrawals','arrow-up')}${statCard('Time-weighted return',pct(s.period_return),'Flow-adjusted total return','chart')}${statCard('Money-weighted return',pct(s.xirr),'XIRR · annualized','activity')}</div>
 <div class="ledger-layout"><section class="card full-card"><div class="card-title-row"><div><div class="card-title">Record a transaction</div><div class="card-subtitle">All records persist locally in SQLite</div></div></div>${readonly?`<div class="ledger-sample-steps"><div class="sample-step-heading">Walk through a real accounting workflow</div><div class="sample-step"><b>01 / Fund the account</b><span>A $30,000 deposit creates cash, not investment return.</span></div><div class="sample-step"><b>02 / Build positions</b><span>Two fictional assets are purchased, with share quantity and basis tracked independently.</span></div><div class="sample-step"><b>03 / Record events</b><span>Additional deposits, a dividend, sale, fee and withdrawal change investor cash flows and holdings.</span></div><div class="sample-step"><b>04 / Measure performance</b><span>Daily TWR removes external contributions; XIRR reflects their timing.</span></div><button class="btn btn-primary" data-action="new-ledger">${svg('arrow',14)} Create my own ledger</button></div>`:`<form id="ledgerTransactionForm" class="ledger-form"><label>Date<input class="form-control" type="date" name="occurred_on" value="${new Date().toISOString().slice(0,10)}" required></label><label>Type<select class="form-control" name="kind" id="txKind">${types.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Ticker (for trades/splits)<input class="form-control" name="symbol" maxlength="16" placeholder="e.g. MSFT"></label><label>Quantity (buy/sell)<input class="form-control" type="number" name="quantity" step="any" min="0" placeholder="0"></label><label>Execution price / split ratio<input class="form-control" type="number" name="unit_price" step="any" min="0" placeholder="0"></label><label>Cash amount (deposit, dividend, fee)<input class="form-control" type="number" name="amount" step="any" min="0" placeholder="0"></label><label>Security name (new buys)<input class="form-control" name="name" placeholder="Optional"></label><label>Sector<input class="form-control" name="sector" placeholder="Technology"></label><label>Asset class<select class="form-control" name="asset_class">${['Equity','ETF','Fixed Income','Commodity ETF','Cash Equivalent'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Memo<input class="form-control" name="memo" maxlength="240" placeholder="Optional note"></label><button type="submit" class="btn btn-primary">${svg('check',15)} Save transaction</button></form><div class="notice">Start with DEPOSIT. BUY/SELL use quantity × execution price; SPLIT uses the after/before share ratio in the price field. DIVIDEND/FEE use a cash amount. Fees require an independent transaction.</div>`}</section>
 <section class="card full-card"><div class="card-title-row"><div><div class="card-title">Historical closing prices</div><div class="card-subtitle">No invented observations, ever</div></div></div><p class="helper">CSV format: <code>symbol,date,close</code>. Use raw <b>unadjusted</b> closes and record dividends/splits in the ledger to avoid double counting. Closing prices can be delayed or unavailable. Demo bars are fictional.</p><form id="priceCSVForm" class="ledger-import-form"><input class="form-control" type="file" name="file" accept=".csv,text/csv" required><button class="btn btn-primary" type="submit">${svg('upload',14)} Import prices CSV</button></form><a class="download-example" href="/static/sample_prices.csv" download>Download example price CSV ${svg('download',12)}</a><div class="divider"></div><div class="card-title">Optional provider sync</div><p class="helper">To fetch real historical daily closes, set <code>TWELVEDATA_API_KEY</code> on your local server. Provider usage, access tiers, licensing and rate limits apply. This does not connect to your broker.</p><form id="syncPricesForm" class="ledger-import-form"><input class="form-control" name="symbol" placeholder="Symbol (e.g., AAPL)" maxlength="16" required><button type="submit" class="btn btn-secondary">${svg('refresh',14)} Sync</button></form><div class="divider"></div><div class="card-title">Bulk transaction import</div><p class="helper">Upload up to 500 ledger transactions, including type, ticker, date, quantity, price and cash amount.</p>${readonly?'<div class="notice">Demo ledger is read-only.</div>':`<form id="ledgerCSVForm" class="ledger-import-form"><input class="form-control" type="file" name="file" accept=".csv,text/csv" required><button type="submit" class="btn btn-secondary">${svg('upload',14)} Import transactions</button></form>`}<a class="download-example" href="/static/sample_transactions.csv" download>Download example transactions CSV ${svg('download',12)}</a></section></div>
 <section class="card full-card"><div class="card-title-row"><div><div class="card-title">Recorded activity</div><div class="card-subtitle">Chronological, auditable transaction record</div></div><span class="tiny-label">${state.transactions.length} EVENTS</span></div><div class="table-scroll"><table class="holdings-table ledger-table"><thead><tr><th>DATE</th><th>TYPE</th><th>SYMBOL</th><th class="right">QTY</th><th class="right">PRICE</th><th class="right">CASH AMOUNT</th></tr></thead><tbody>${state.transactions.length?state.transactions.map(t=>`<tr><td>${esc(t.occurred_on)}</td><td><span class="ticker-swatch">${esc(t.kind)}</span></td><td>${esc(t.symbol||'—')}</td><td class="right">${t.quantity?fmt(t.quantity,4):'—'}</td><td class="right">${t.unit_price?usd(t.unit_price):'—'}</td><td class="right">${t.amount?usd(t.amount):'—'}</td></tr>`).join(''):'<tr><td colspan="6">No transaction records loaded yet.</td></tr>'}</tbody></table></div></section>
 <div class="explain-panel">${svg('shield')}<span>Local single-user research project. No brokerage authorization, live trade execution, production tax-lot handling, or suitability analysis. Close prices are as-of reported dates and never implied to be current.</span></div>`;
}
async function loadTransactions(){if(!state.data?.portfolio.ledger_enabled)return;const id=state.portfolio;try{const r=await api(`/api/portfolio/${encodeURIComponent(id)}/transactions`);if(state.portfolio===id){state.transactions=r.transactions;if(state.view==='ledger')render();}}catch(err){toast(err.message,true)}}
async function createLedger(form){const submit=$('button[type=submit]',form);submit.disabled=true;try{const r=await api('/api/ledger',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:form.elements.name.value})});state.portfolios=await api('/api/portfolios');$('#newLedgerModal')?.remove();await loadPortfolio(r.id);toast('Ledger portfolio created. Start with a DEPOSIT transaction.')}catch(err){toast(err.message,true)}finally{submit.disabled=false}}
async function postTransaction(form){const submit=$('button[type=submit]',form);submit.disabled=true;const id=state.portfolio;const payload={};for(const [k,v] of new FormData(form).entries()){payload[k]=['quantity','unit_price','amount'].includes(k)?Number(v||0):v}try{await api(`/api/portfolio/${encodeURIComponent(id)}/transactions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadPortfolio(id);await loadTransactions();toast('Transaction saved and portfolio reconciled')}catch(err){toast(err.message,true)}finally{submit.disabled=false}}
async function uploadCSV(form,endpoint){const input=$('input[type=file]',form),file=input.files[0];if(!file)return;const button=$('button[type=submit]',form);button.disabled=true;const fd=new FormData();fd.append('file',file);try{const r=await api(endpoint,{method:'POST',body:fd});await loadPortfolio(state.portfolio);await loadTransactions();toast(`${r.imported} records imported`)}catch(err){toast(err.message,true)}finally{button.disabled=false}}
async function postLedgerCSV(form){await uploadCSV(form,`/api/portfolio/${encodeURIComponent(state.portfolio)}/transactions/csv`)}
async function postPricesCSV(form){await uploadCSV(form,'/api/prices/import/csv')}
async function syncPrices(form){const button=$('button[type=submit]',form);button.disabled=true;try{const r=await api('/api/prices/twelvedata/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbol:form.elements.symbol.value})});await loadPortfolio(state.portfolio);await loadTransactions();toast(`Imported ${r.imported} daily closes for ${r.symbol}`)}catch(err){toast(err.message,true)}finally{button.disabled=false}}
function openCreateLedger(){if(!state.data?.portfolio.ledger_enabled){setView('ledger');return}const cover=document.createElement('div');cover.className='import-modal-backdrop';cover.id='newLedgerModal';cover.innerHTML=`<div class="import-modal" role="dialog" aria-modal="true" aria-label="Create a ledger portfolio"><div class="modal-title"><h2>New transaction ledger</h2><button class="icon-btn" data-action="close-ledger-modal" aria-label="Close dialog">${svg('cross',19)}</button></div><p class="helper">Create a separate ledger. Your other portfolios and imports are preserved.</p><form id="ledgerCreateForm"><div class="form-group"><label>Portfolio name<input class="form-control" name="name" value="My Investment Ledger" maxlength="75" required></label></div><div class="modal-buttons"><button class="btn btn-primary" type="submit">Create ledger</button></div></form></div>`;document.body.appendChild(cover);cover.addEventListener('click',e=>{if(e.target===cover)cover.remove()});}
function renderXray(){
 const d=state.data,x=state.xray;
 const head=pageHeader('PORTFOLIO X-RAY','See what you actually own','Uncover overlapping ETF positions and quantify how much fund exposure is still unknown.')+banner();
 if(!x)return head+`<section class="card full-card"><div class="initial-loading"><div class="loading-ring"></div>Computing fund exposure…</div></section>`;
 if(!x.available)return head+`<section class="card full-card"><div class="empty-state"><h3>Price coverage required</h3><p>${esc(x.reason)}</p></div></section>`;
 const z=x.summary;
 const kpis=`<div class="grid stats-grid">
 ${statCard('Fund constituent coverage',z.fund_coverage_pct==null?'N/A':fmt(z.fund_coverage_pct,1)+'%','Value-weighted known fund constituents','layers','hero')}
 ${statCard('Shared underlying companies',fmt(z.duplicated_constituents),'Present through multiple sources','pie')}
 ${statCard('Multi-source exposure',fmt(z.multi_source_exposure_pct,1)+'%','Total exposure to companies held through 2+ sources','activity')}
 ${statCard('Unmapped fund value',usd(z.unknown_fund_value),'Not assumed to be zero risk','alert')}</div>`;
 const sectorRows=x.sectors.map(s=>`<div class="xray-sector"><div><span>${esc(s.name)}</span><b>${fmt(s.weight_pct,2)}%</b></div><div class="xray-meter"><span style="width:${Math.min(100,Math.max(0,s.weight_pct))}%"></span></div></div>`).join('');
 const fundRows=x.funds.map(f=>`<tr><td><b>${esc(f.symbol)}</b></td><td>${fmt(f.covered_pct,2)}%</td><td>${esc(f.as_of||'Not supplied')}</td><td>${esc(f.source||'No constituent file imported')}</td><td class="right">${usd(f.unmapped_value)}</td></tr>`).join('');
 const trows=x.underlyings.slice(0,40).map(h=>`<tr><td><b>${esc(h.symbol)}</b><small style="display:block;color:var(--muted)">${esc(h.sector)}</small></td><td>${usd(h.value)}</td><td>${fmt(h.weight_pct,2)}%</td><td>${h.sources.map(q=>`<span class="source-pill">${esc(q.symbol)}: ${usd(q.value)}</span>`).join('')}</td><td><span class="${h.source_count>1?'positive':'muted'}">${h.source_count>1?'Shared':'Single source'}</span></td></tr>`).join('');
 return head+`<div class="data-banner">${svg('alert')}<span><b>${x.mode==='fictional_demo'?'Fictional ETF weights':'User-provided fund snapshots'}.</b> ${esc(x.warning)}</span></div>${kpis}
 <div class="xray-grid">
 <section class="card full-card"><div class="card-title">Underlying sector exposures</div><div class="card-subtitle">Portfolio-weighted look-through, including uncovered fund value and cash</div><div class="xray-sectors">${sectorRows}</div></section>
 <section class="card full-card"><div class="card-title">Constituent data coverage</div><p class="helper">A 25% constituent disclosure means that 75% of that ETF remains unclassified. This is not 75% cash.</p><div class="xray-coverage-number">${fmt(100-z.unknown_portfolio_pct,2)}%<small>of the portfolio is directly classified or mapped through disclosed fund constituents</small></div><div class="divider"></div><p class="helper">${esc(x.methodology)}</p><button class="btn btn-secondary" data-action="refresh-xray">${svg('refresh',14)} Refresh calculation</button></section></div>
 <section class="card full-card"><div class="card-title-row"><div><div class="card-title">Underlying holdings and shared exposures</div><div class="card-subtitle">Overlaps are additive underlying exposures, not extra assets or guaranteed losses</div></div><span class="tiny-label">${x.underlyings.length} KNOWN SECURITIES</span></div><div class="table-scroll"><table class="holdings-table xray-table"><thead><tr><th>UNDERLYING</th><th>VALUE</th><th>PORTFOLIO %</th><th>DIRECT / FUND SOURCES</th><th>OVERLAP</th></tr></thead><tbody>${trows||'<tr><td colspan="5">No known constituents yet. Import a dated file below.</td></tr>'}</tbody></table></div></section>
 <section class="card full-card"><div class="card-title">Fund constituent snapshots</div><p class="helper">Each portfolio owns its own fund snapshots. A replacement import updates only funds included in that file. Rows for other funds remain unchanged.</p><div class="table-scroll"><table class="holdings-table xray-table"><thead><tr><th>FUND</th><th>COVERED</th><th>AS-OF DATE</th><th>SOURCE</th><th class="right">UNMAPPED VALUE</th></tr></thead><tbody>${fundRows||'<tr><td colspan="5">No ETF fund holdings in this portfolio.</td></tr>'}</tbody></table></div>
 <div class="divider"></div><div class="card-title">Import constituent holdings</div><p class="helper">CSV: <code>fund_symbol,underlying_symbol,sector,weight_pct,as_of,source</code>. The <code>weight_pct</code> is the percentage of each fund (not the total portfolio). One as-of date and source per fund. A fund snapshot can be partial (below 100%).</p>${d.portfolio.is_demo?'<div class="notice">Fictional demo snapshots are read-only. Create or import a separate portfolio to add dated constituent data.</div>':`<form id="fundCSVForm" class="ledger-import-form"><input type="file" class="form-control" accept=".csv,text/csv" name="file" required><button type="submit" class="btn btn-primary">${svg('upload',14)} Import fund holdings</button></form>`}<a class="download-example" href="/static/sample_constituents.csv" download>Download sample constituent CSV ${svg('download',12)}</a></section>`;
}
async function loadXray(){if(!state.data)return;const id=state.portfolio;try{const r=await api(`/api/portfolio/${encodeURIComponent(id)}/xray`);if(id!==state.portfolio)return;state.xray=r;if(state.view==='xray')render();}catch(err){toast(err.message,true)}}
async function postFundCSV(form){const file=form.elements.file.files[0];if(!file)return;const b=$('button[type=submit]',form);b.disabled=true;const fd=new FormData();fd.append('file',file);try{const r=await api(`/api/portfolio/${encodeURIComponent(state.portfolio)}/xray/constituents/csv`,{method:'POST',body:fd});await loadXray();state.stressCompare=null;toast(`Updated ${r.funds_updated.length} fund snapshots (${r.constituent_rows} constituents)`)}catch(err){toast(err.message,true)}finally{b.disabled=false}}
function advancedStressPanel(){
 const results=state.stressCompare;
 const cards=results?results.map(s=>`<button class="stress-choice ${state.stressDetail?.preset===s.preset?'chosen':''}" data-advanced-preset="${esc(s.preset)}"><b>${esc(s.title)}</b><span class="${colorClass(s.change)}">${pct(s.change_pct)} · ${signedUSD(s.change)}</span></button>`).join(''):`<div class="helper">Loading scenario comparison…</div>`;
 const detail=state.stressDetail;
 const breakdown=detail?`<div class="stress-detail"><div class="card-title-row"><div><div class="card-title">${esc(detail.title)}</div><div class="card-subtitle">${esc(detail.description)}</div></div><span class="${colorClass(detail.change)}">${signedUSD(detail.change)} (${pct(detail.change_pct)})</span></div><div class="table-scroll"><table class="holdings-table"><thead><tr><th>EXPOSURE</th><th class="right">ASSUMED SHOCK</th><th class="right">P/L IMPACT</th></tr></thead><tbody>${detail.breakdown.map(h=>`<tr><td>${esc(h.sector)}</td><td class="right">${pct(h.shock_pct,1)}</td><td class="right ${colorClass(h.impact)}">${signedUSD(h.impact)}</td></tr>`).join('')}</tbody></table></div><p class="notice">${esc(detail.methodology)}</p></div>`:'';
 const sectors=state.xray?.available?state.xray.sectors.map(s=>`<option value="${esc(s.name)}">${esc(s.name)}</option>`).join(''):'<option value="Technology">Technology</option>';
 return `<section class="card full-card advanced-stress"><div class="card-title-row"><div><div class="eyebrow">PHASE 3 / LOOK-THROUGH STRESS</div><div class="card-title">Advanced exposure scenarios</div><div class="card-subtitle">Model shocks on ETF constituent exposures and direct holdings; uncovered portions stay explicit.</div></div></div>
 <div class="stress-grid">${cards}</div>${detail||results?breakdown:''}
 <div class="divider"></div><div class="card-title">Build your own sector stress</div><p class="helper">Set an overall default shock and override one sector. Cash remains flat unless explicitly selected. Values are assumptions, not predictions.</p>
 <form class="stress-custom" id="advancedStressForm"><label>Default shock %<input class="form-control" name="base" type="number" min="-100" max="200" step="1" value="-10" required></label><label>Sector override<select class="form-control" name="sector">${sectors}</select></label><label>Sector shock %<input class="form-control" name="shock" type="number" min="-100" max="200" step="1" value="-30" required></label><button class="btn btn-primary" type="submit">${svg('sliders',15)} Run custom model</button></form>
 <p class="notice">Fund data is sourced from dated constituent snapshots or clearly fictional demos. Missing ETF constituents receive an explicit scenario assumption without invented underlying positions.</p></section>`;
}
async function loadStressCompare(){if(!state.data)return;const id=state.portfolio;try{const r=await api(`/api/portfolio/${encodeURIComponent(id)}/stress/compare`);if(id!==state.portfolio)return;state.stressCompare=r.results;if(!state.stressDetail)state.stressDetail=r.results[1];if(state.view==='scenarios')render();}catch(err){state.stressCompare=[];if(state.view==='scenarios')render();}}
async function runAdvancedStress(preset){if(!state.data)return;const id=state.portfolio;try{const r=await api(`/api/portfolio/${encodeURIComponent(id)}/stress/advanced`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({preset})});if(state.portfolio===id){state.stressDetail=r;render()}}catch(err){toast(err.message,true)}}
async function runCustomStress(form){const sector=form.elements.sector.value;const shock=Number(form.elements.shock.value);const base=Number(form.elements.base.value);const id=state.portfolio;try{const r=await api(`/api/portfolio/${encodeURIComponent(id)}/stress/advanced`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({preset:'custom',default_pct:base,sector_shocks:{[sector]:shock}})});if(id===state.portfolio){state.stressDetail=r;render()}}catch(err){toast(err.message,true)}}
const _renderScenariosV2=renderScenarios;
renderScenarios=function(){return _renderScenariosV2()+advancedStressPanel()};
const _renderAnalystV2=renderAnalyst;
renderAnalyst=function(){
 const original=_renderAnalystV2();
 const toggle=`<div class="ai-consent"><label><input type="checkbox" id="aiConsent" ${state.useAI?'checked':''}> Use live AI analyst (OpenAI API)</label><small>${state.aiAvailable?'API key configured on server. Checking this sends your question and selected portfolio calculations to OpenAI.':'Offline guided analyst works without an API key. Set OPENAI_API_KEY on your local server to enable live AI.'} Requests are never sent to OpenAI without this opt-in. API usage may incur fees.</small></div>`;
 return original.replace('<div class="analyst-layout">',toggle+'<div class="analyst-layout">')
  .replace('GUIDED MODE',state.useAI?'AI / TOOL-GROUNDED':'GUIDED MODE')
  .replace('Guided answers, not a large language model. Educational use only.',state.useAI?'AI-generated answers may contain errors; verify figures. Educational use only.':'Guided, local answers based on financial calculations. Educational use only.')
  .replace('This first release uses deterministic financial tools and guided answer templates. It does not make unverified LLM claims or execute investment trades.','Guided mode uses deterministic calculation-grounded explanations. Live AI is opt-in, uses read-only calculation tools, and does not execute trades or issue personalized orders.')
  .replace('No brokerage credentials or external AI service are needed.','Only the optional live AI setting sends selected portfolio data to a provider; guided mode is local.');
};

function setView(view){if(!pageNames[view])return;state.view=view;state.search='';render();window.scrollTo({top:0,behavior:'instant'});$('#sidebar').classList.remove('open');if(view==='risk')loadCorrelations();if(view==='xray')loadXray();if(view==='scenarios'){loadXray();loadStressCompare();}if(view==='scenarios')runScenario();if(view==='ledger')loadTransactions();}
function render(){const views={overview:renderOverview,holdings:renderHoldings,xray:renderXray,risk:renderRisk,scenarios:renderScenarios,analyst:renderAnalyst,ledger:renderLedger,methodology:renderMethodology};$('#currentBreadcrumb').textContent=pageNames[state.view];$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#content').innerHTML=state.data?views[state.view]():`<div class="initial-loading"><div class="loading-ring"></div>Loading portfolio...</div>`;if(state.view==='analyst'){let el=$('#chatArea');if(el)el.scrollTop=el.scrollHeight;}}
async function loadPortfolio(slug){state.portfolio=slug;state.transactions=[];state.xray=null;state.stressCompare=null;state.stressDetail=null;state.chat=[];state.scenarioResult=null;state.search='';state.data=null;render();try{state.data=await api(`/api/portfolio/${encodeURIComponent(slug)}/dashboard`);render();if(state.view==='risk')loadCorrelations();if(state.view==='xray')loadXray();if(state.view==='scenarios'){loadXray();loadStressCompare();}if(state.view==='scenarios')runScenario();if(state.view==='ledger')loadTransactions();}catch(err){$('#content').innerHTML=`<div class="empty-state"><h3>Unable to load portfolio</h3><p>${esc(err.message)}</p></div>`;toast(err.message,true)}}
async function loadCorrelations(){if(!state.data)return;const portfolioId=state.portfolio;try{const r=await api(`/api/portfolio/${encodeURIComponent(portfolioId)}/correlations`);if(state.view==='risk'&&state.portfolio===portfolioId){const el=$('#correlationContainer');if(el){el.className='';el.innerHTML=heatmap(r.data)}}}catch(e){toast(e.message,true)}}
async function runScenario(){const id=state.portfolio;const preset=state.scenarioPreset;const shocks=preset==='custom'?state.shocks:{};try{const res=await api(`/api/portfolio/${encodeURIComponent(id)}/scenario`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({preset,shocks})});if(state.view==='scenarios'&&state.portfolio===id&&state.scenarioPreset===preset){state.scenarioResult=res;const el=$('#scenarioResults');if(el)el.innerHTML=scenarioResultHTML(res)}}catch(err){toast(err.message,true)}}
async function askAnalyst(text){const question=text.trim();if(question.length<3)return;const id=state.portfolio;state.chat.push({role:'user',text:question});render();try{const r=await api(`/api/portfolio/${encodeURIComponent(id)}/analyst`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,use_ai:state.useAI})});if(state.portfolio!==id)return;state.chat.push({role:'assistant',text:r.answer,sources:r.sources});render()}catch(err){state.chat.push({role:'assistant',text:'Unable to calculate an answer: '+err.message});render()}}
function openImport(){const cover=document.createElement('div');cover.className='import-modal-backdrop';cover.id='importBackdrop';cover.innerHTML=`<div class="import-modal" role="dialog" aria-modal="true" aria-label="Import holdings"><div class="modal-title"><h2>Import your holdings</h2><button class="icon-btn" data-action="close-import" aria-label="Close dialog">${svg('cross',19)}</button></div><p class="helper">Upload a CSV containing current positions. No broker sign-in, live price lookup, or external service required.</p><form id="importForm"><div class="form-group"><label for="importName">Portfolio name</label><input class="form-control" id="importName" value="My Investment Portfolio" maxlength="75" required/></div><div class="form-group"><label for="importFile">Positions CSV</label><input class="form-control" id="importFile" type="file" accept=".csv,text/csv" required/><p class="helper">Required columns: symbol, name, sector, asset_class, quantity, avg_cost, current_price. Up to 100 symbols · 250 KB.</p></div><div class="modal-buttons"><button type="button" class="btn btn-secondary" data-action="close-import">Cancel</button><button type="submit" class="btn btn-primary">${svg('upload',14)} Import CSV</button></div></form><p class="helper">See <a href="/static/sample_portfolio.csv" download>example CSV</a>. Your data is stored in a local SQLite database. Do not expose this demo to the public internet.</p></div>`;document.body.appendChild(cover);cover.addEventListener('click',e=>{if(e.target===cover)cover.remove()});$('#importName').focus()}
function exportCurrent(){const cols=['symbol','name','sector','asset_class','quantity','avg_cost','current_price'];const rows=[cols.join(','),...state.data.holdings.map(row=>cols.map(k=>`"${String(row[k]??'').replace(/"/g,'""')}"`).join(','))];const blob=new Blob([rows.join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='portfolioiq_'+state.portfolio+'_holdings.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500)}
async function doImport(form){const file=$('#importFile').files[0];const name=$('#importName').value.trim();if(!file)return toast('Choose a CSV file first',true);const submit=$('button[type=submit]',form);submit.disabled=true;submit.textContent='Importing...';const fd=new FormData();fd.append('file',file);try{const r=await api(`/api/import/csv?name=${encodeURIComponent(name)}`,{method:'POST',body:fd});$('#importBackdrop').remove();state.portfolios=await api('/api/portfolios');state.view='overview';await loadPortfolio(r.id);toast(`Imported ${r.count} holdings successfully`)}catch(err){toast(err.message,true);submit.disabled=false;submit.textContent='Import CSV'}}
function addEvents(){document.addEventListener('click',async e=>{
 const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return}
 const period=e.target.closest('[data-period]');if(period){state.period=period.dataset.period;render();return}
 const preset=e.target.closest('[data-preset]');if(preset){state.scenarioPreset=preset.dataset.preset;state.shocks={...PRESETS[state.scenarioPreset].shocks};state.scenarioResult=null;render();runScenario();return}
 const prompt=e.target.closest('[data-prompt]');if(prompt){askAnalyst(prompt.dataset.prompt);return}
 const stress=e.target.closest('[data-advanced-preset]');if(stress){runAdvancedStress(stress.dataset.advancedPreset);return}
 const action=e.target.closest('[data-action]');if(action){const type=action.dataset.action;if(type==='import')openImport();if(type==='close-import')$('#importBackdrop')?.remove();if(type==='close-ledger-modal')$('#newLedgerModal')?.remove();if(type==='run-scenario')runScenario();if(type==='export')exportCurrent();if(type==='create-ledger'||type==='new-ledger')openCreateLedger();if(type==='refresh-xray')loadXray();return}
 });
 document.addEventListener('change',e=>{if(e.target.id==='aiConsent'){state.useAI=e.target.checked;render();}if(e.target.id==='portfolioSelect'){loadPortfolio(e.target.value)}if(e.target.id==='sortSelect'){state.sort=e.target.value;holdingsSearchUpdate()}});
 document.addEventListener('input',e=>{if(e.target.id==='holdingsSearch'){state.search=e.target.value;holdingsSearchUpdate()}if(e.target.dataset.shock){const key=e.target.dataset.shock;state.shocks[key]=Number(e.target.value);const label=$(`#sliderLabel_${key}`);if(label)label.textContent=pct(state.shocks[key],0)}});
 document.addEventListener('submit',e=>{if(e.target.id==='chatForm'){e.preventDefault();const input=$('#chatInput');const text=input.value;input.value='';askAnalyst(text)}if(e.target.id==='importForm'){e.preventDefault();doImport(e.target)}if(e.target.id==='ledgerCreateForm'){e.preventDefault();createLedger(e.target)}if(e.target.id==='ledgerTransactionForm'){e.preventDefault();postTransaction(e.target)}if(e.target.id==='ledgerCSVForm'){e.preventDefault();postLedgerCSV(e.target)}if(e.target.id==='priceCSVForm'){e.preventDefault();postPricesCSV(e.target)}if(e.target.id==='syncPricesForm'){e.preventDefault();syncPrices(e.target)}if(e.target.id==='fundCSVForm'){e.preventDefault();postFundCSV(e.target)}if(e.target.id==='advancedStressForm'){e.preventDefault();runCustomStress(e.target)}});
 $('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
 $('#aboutButton').addEventListener('click',()=>setView('methodology'));
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#newLedgerModal')?.remove();$('#importBackdrop')?.remove();$('#sidebar').classList.remove('open')}})
}
async function init(){fillStaticIcons();addEvents();try{const health=await api('/api/health');state.aiAvailable=health.ai_mode==='opt_in_llm_available';state.portfolios=await api('/api/portfolios');await loadPortfolio(state.portfolio)}catch(err){$('#content').innerHTML=`<div class="empty-state"><h3>Unable to connect to PortfolioIQ</h3><p>${esc(err.message)}</p><p>Start the FastAPI server and refresh.</p></div>`;toast(err.message,true)}}
init();
